class TestTemporalConsistency:
    """Validate temporal ordering and consistency of acquisition timestamps."""

    def test_timestamps_are_monotonically_increasing(self, validated_allocations):
        """Acquisition timestamps should be in non-decreasing order by port number."""
        sorted_ports = sorted(validated_allocations.allocations.items(), key=lambda x: int(x[0]))
        timestamps = [
            datetime.fromisoformat(alloc.acquired_at)
            for _, alloc in sorted_ports
        ]
        for i in range(1, len(timestamps)):
            assert timestamps[i] >= timestamps[i-1], (
                f"Timestamp at port {sorted_ports[i][0]} is earlier than previous"
            )

    def test_all_timestamps_in_utc(self, validated_allocations):
        """All timestamps must be timezone-aware and in UTC."""
        for port, alloc in validated_allocations.allocations.items():
            dt = datetime.fromisoformat(alloc.acquired_at)
            assert dt.tzinfo is not None, f"Port {port} has naive timestamp"
            assert dt.tzinfo.utcoffset(dt) == timezone.utc.utcoffset(dt), (
                f"Port {port} timestamp is not UTC"
            )

    @freeze_time("2026-07-07T14:50:00.000000+00:00")
    def test_no_future_timestamps(self, validated_allocations):
        """No acquisition timestamp should be in the future."""
        now = datetime.now(timezone.utc)
        for port, alloc in validated_allocations.allocations.items():
            dt = datetime.fromisoformat(alloc.acquired_at)
            assert dt <= now, f"Port {port} has future timestamp: {dt}"


