class TestConcurrency:
    """Simulate concurrent access patterns to detect race conditions."""

    def test_concurrent_reads_are_thread_safe(self, sample_allocations):
        """Multiple threads reading the allocations must not cause errors."""
        errors = []
        lock = threading.Lock()

        def read_allocations():
            try:
                for _ in range(100):
                    model = PortAllocations(allocations=sample_allocations)
                    _ = model.model_dump()
            except Exception as e:
                with lock:
                    errors.append(e)

        threads = [threading.Thread(target=read_allocations) for _ in range(10)]
        for t in threads:
            t.start()
        for t in threads:
            t.join()

        assert len(errors) == 0, f"Concurrent reads produced {len(errors)} errors"

    def test_concurrent_writes_do_not_corrupt_state(self):
        """Simulate concurrent allocation and deallocation of ports."""
        shared_state = {}
        lock = threading.Lock()
        errors = []

        def allocate_port(port: str, agent: str, card: str):
            try:
                with lock:
                    shared_state[port] = {
                        "agent_id": agent,
                        "purpose": f"card-{card}",
                        "acquired_at": datetime.now(timezone.utc).isoformat()
                    }
                    # Validate immediately after write
                    PortAllocations(allocations=shared_state)
            except Exception as e:
                with lock:
                    errors.append(e)

        def deallocate_port(port: str):
            try:
                with lock:
                    if port in shared_state:
                        del shared_state[port]
                    PortAllocations(allocations=shared_state)
            except Exception as e:
                with lock:
                    errors.append(e)

        threads = []
        for i in range(20):
            port = str(9000 + i)
            threads.append(threading.Thread(target=allocate_port, args=(port, f"agent-{i}", f"{i:08x}")))
        for i in range(10):
            port = str(9000 + i)
            threads.append(threading.Thread(target=deallocate_port, args=(port,)))

        for t in threads:
            t.start()
        for t in threads:
            t.join()

        assert len(errors) == 0, f"Concurrent writes produced {len(errors)} errors"
        # Final state must be valid
        PortAllocations(allocations=shared_state)


