class TestPerformance:
    """Ensure validation performs adequately under load."""

    def test_large_allocation_set_validates_quickly(self):
        """Validating 1000 allocations must complete within 1 second."""
        large_data = {}
        for i in range(1000):
            port = str(1024 + i)
            large_data[port] = {
                "agent_id": f"agent-{i}",
                "purpose": f"card-{i:08x}",
                "acquired_at": f"2026-07-07T14:44:40.{i:06d}+00:00"
            }

        start = time.time()
        model = PortAllocations(allocations=large_data)
        elapsed = time.time() - start

        assert elapsed < 1.0, f"Validation took {elapsed:.2f}s (expected < 1.0s)"
        assert len(model.allocations) == 1000

    def test_memory_usage_with_large_dataset(self):
        """Memory should not grow unboundedly with large datasets."""
        import tracemalloc

        tracemalloc.start()
        large_data = {}
        for i in range(5000):
            port = str(1024 + i)
            large_data[port] = {
                "agent_id": f"agent-{i}",
                "purpose": f"card-{i:08x}",
                "acquired_at": f"2026-07-07T14:44:40.{i:06d}+00:00"
            }

        model = PortAllocations(allocations=large_data)
        current, peak = tracemalloc.get_traced_memory()
        tracemalloc.stop()

        # Peak memory should be reasonable (< 50 MB for 5000 entries)
        assert peak < 50 * 1024 * 1024, f"Peak memory usage: {peak / 1024 / 1024:.2f} MB"


