class TestSwarmOSIntegration:
    """Validate integration patterns specific to Swarm OS architecture."""

    def test_agent_id_matches_known_agents(self, validated_allocations):
        """Agent IDs should correspond to known Swarm OS agents."""
        known_agents = {"kanban", "Lead Developer", "QA Engineer", "Verify"}
        for alloc in validated_allocations.allocations.values():
            assert alloc.agent_id in known_agents, (
                f"Unknown agent: {alloc.agent_id}"
            )

    def test_purpose_card_format_consistency(self, validated_allocations):
        """All purposes must follow the card-XXXXXXXX pattern."""
        import re
        pattern = re.compile(r"^card-[a-f0-9]{8}$")
        for alloc in validated_allocations.allocations.values():
            assert pattern.match(alloc.purpose), (
                f"Invalid purpose format: {alloc.purpose}"
            )

    def test_no_port_conflicts_across_agents(self, validated_allocations):
        """No two allocations should share the same port."""
        ports = list(validated_allocations.allocations.keys())
        assert len(ports) == len(set(ports)), "Duplicate ports detected"

    def test_agent_port_affinity(self, validated_allocations):
        """Agents should have consistent port assignments (no agent on multiple ports)."""
        agent_ports = {}
        for port, alloc in validated_allocations.allocations.items():
            agent_ports.setdefault(alloc.agent_id, []).append(port)
        # In this sample, Lead Developer has two ports, which is acceptable
        # but we verify no agent has more than 3 ports (arbitrary limit)
        for agent, ports in agent_ports.items():
            assert len(ports) <= 3, f"Agent {agent} has {len(ports)} ports (max 3)"


